import{_ as e}from"./chunks/library-overview.Bu864uIA.js";import{_ as d,o as a,c as o,a2 as s}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"图库与导入","description":"图库在每次应用加载时扫描 raw/ 文件夹构建而成。没有数据库，也没有复制图片的导入步骤：目录结构本身就是配置。","frontmatter":{"description":"图库在每次应用加载时扫描 raw/ 文件夹构建而成。没有数据库，也没有复制图片的导入步骤：目录结构本身就是配置。"},"headers":[],"relativePath":"zh/guide/gallery.md","filePath":"zh/guide/gallery.md","lastUpdated":1794725747000}'),n={name:"zh/guide/gallery.md"};function i(r,t,c,l,h,p){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="图库与导入" tabindex="-1">图库与导入 <a class="header-anchor" href="#图库与导入" aria-label="Permalink to &quot;图库与导入&quot;">​</a></h1><p>图库在每次应用加载时扫描 <code>raw/</code> 文件夹构建而成。没有数据库，也没有复制图片的导入步骤：<strong>目录结构本身就是配置</strong>。</p><p>本页介绍如何组织文件、扫描器如何配对语言、如何添加位于其他位置的文件夹，以及有哪些导入入口。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>漫画扫描片的文件夹结构千奇百怪：<code>Vol.14/Japanese/ch01</code>、<code>点兔第14卷/ja/172</code>、<code>manga/zh-cn/172</code>。你希望有一个书架统一列出卷和话，把每种语言的第 1 页与其他语言的第 1 页配对，并在缺文件时告诉你缺在哪里——而不用重命名或移动任何东西。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>  &lt;volume&gt;/</span></span>
<span class="line"><span>    &lt;language-dir&gt;/</span></span>
<span class="line"><span>      &lt;chapter&gt;/</span></span>
<span class="line"><span>        001.jpg</span></span>
<span class="line"><span>        002.jpg</span></span></code></pre></div><ul><li><strong>卷</strong> 是 <code>raw/</code> 下的任意一级文件夹。</li><li><strong>话</strong> 是语言目录内的任意文件夹。各语言的话会取并集，因此某种语言可能缺少某一话的文件夹。</li><li><strong>页面按排序位置配对，而不是按文件名。</strong> 每种语言的文件先做自然排序（连续数字按数值比较），再按索引配对。<code>1.jpg</code>、<code>2.jpg</code>、<code>10.jpg</code> 能正确排序。</li></ul><figure class="shot"><img src="`+e+`" alt="图库侧栏，含卷、话与语言标记"><figcaption>侧栏按 卷 → 话 → 页 列出。语言标记显示该卷存在哪些语言；警告会就地显示。</figcaption></figure><h2 id="语言目录名" tabindex="-1">语言目录名 <a class="header-anchor" href="#语言目录名" aria-label="Permalink to &quot;语言目录名&quot;">​</a></h2><p>扫描器会先规范化文件夹名（转小写，空格和下划线转为连字符），再与别名匹配：</p><table tabindex="0"><thead><tr><th>语言</th><th>可识别的目录名</th></tr></thead><tbody><tr><td>日语（<code>ja</code>）</td><td><code>ja</code>、<code>jp</code>、<code>jpn</code>、<code>japanese</code>、<code>ja-jp</code>、<code>日</code>、<code>日本語</code>、<code>日文</code></td></tr><tr><td>中文（<code>zh</code>）</td><td><code>zh</code>、<code>zh-cn</code>、<code>zh-hans</code>、<code>zh-sg</code>、<code>cn</code>、<code>chs</code>、<code>zh-tw</code>、<code>zh-hk</code>、<code>zh-hant</code>、<code>cht</code>、<code>tw</code>、<code>hk</code>、<code>中</code>、<code>中文</code>、<code>繁中</code>、<code>简中</code></td></tr><tr><td>英语（<code>en</code>）</td><td><code>en</code>、<code>en-us</code>、<code>en-gb</code>、<code>us</code>、<code>uk</code>、<code>eng</code>、<code>english</code>、<code>英</code>、<code>英文</code></td></tr></tbody></table><p>如果文件夹名无法识别，该卷仍会出现在图库中，但会带一条警告。打开 <strong>卷设置</strong>（卷所在行的齿轮）把目录指定为某种语言。选择保存在 <code>data/library.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;volumes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;点兔第14卷&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;dirs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>一卷可以有一种、两种或三种语言。对照阅读只提供当前页实际存在的语言。</p><h2 id="添加位于其他位置的文件夹" tabindex="-1">添加位于其他位置的文件夹 <a class="header-anchor" href="#添加位于其他位置的文件夹" aria-label="Permalink to &quot;添加位于其他位置的文件夹&quot;">​</a></h2><p><strong>＋ 添加漫画</strong> 有两种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>结果</th></tr></thead><tbody><tr><td>路径留空</td><td>在 <code>raw/</code> 下创建一个空文件夹。</td></tr><tr><td>选择已有文件夹</td><td>在 <code>raw/</code> 下创建一个指向原目录的<strong>目录链接</strong>。图片不会被复制；链接的行为与普通文件夹一致，因此标注仍可正常写入。</td></tr></tbody></table><p>可选：为这一卷指定一个不同的显示名称。输入框下方的提示会重申预期的目录结构：<code>language/chapter/page.jpg</code>。</p><p><strong>从图库移除</strong>（位于卷设置）只删除 <code>raw/</code> 下的链接；原文件夹中的图片不受影响，已经保存到 <code>data/pages/</code> 的标注也会保留。</p><p>在普通浏览器中无法弹出文件夹选择框。请直接填写绝对路径，或使用桌面版并点击 <strong>选择文件夹…</strong>。</p><h2 id="页面与语言的角色" tabindex="-1">页面与语言的角色 <a class="header-anchor" href="#页面与语言的角色" aria-label="Permalink to &quot;页面与语言的角色&quot;">​</a></h2><p>有三种容易混淆的“角色”：</p><table tabindex="0"><thead><tr><th>角色</th><th>在哪里选择</th><th>影响什么</th></tr></thead><tbody><tr><td><strong>底图</strong></td><td>切格工作台工具栏</td><td>在哪种语言的画面上画分格。分格矩形由该页的所有语言共用。</td></tr><tr><td><strong>对照语言</strong></td><td>对照阅读的语言标签</td><td>显示哪些语言、以什么顺序显示。不必启用所有语言。</td></tr><tr><td><strong>首选语言</strong></td><td>PNG 导出</td><td>整页与单格 PNG 使用基准语言；三语拼图使用所选的对照语言。</td></tr></tbody></table><p>分格与笔记按页面存储一份，而不是每种语言一份。对齐偏移按语言存储，也可以按分格存储。</p><h2 id="你会看到的警告" tabindex="-1">你会看到的警告 <a class="header-anchor" href="#你会看到的警告" aria-label="Permalink to &quot;你会看到的警告&quot;">​</a></h2><p>图库警告只是提示信息，页面仍然可以打开。</p><table tabindex="0"><thead><tr><th>警告</th><th>含义</th><th>处理</th></tr></thead><tbody><tr><td><em>未识别到语言目录</em></td><td>没有任何子文件夹匹配别名。</td><td>在卷设置里手工映射，或重命名。</td></tr><tr><td><em>未识别的目录：…</em></td><td>语言目录旁边还有其他文件夹。</td><td>映射它们，或直接忽略。</td></tr><tr><td><em>各语言页数不一致</em></td><td>各语言的文件数量不同。</td><td>配对按索引进行；补齐或删除缺失的那一页。</td></tr><tr><td><em>本话扩展名混用</em></td><td>例如 <code>.jpg</code> 与 <code>.png</code> 交替出现。</td><td>通常无妨；如果在意缩略图一致，可统一格式。</td></tr><tr><td><em>文件名与页序不符</em></td><td>文件名开头的数字与它的排序位置不一致。</td><td>如果这种不一致意味着缺页或多页，请重命名。</td></tr></tbody></table><h2 id="目录识别规则" tabindex="-1">目录识别规则 <a class="header-anchor" href="#目录识别规则" aria-label="Permalink to &quot;目录识别规则&quot;">​</a></h2><p><strong>目录识别…</strong>（侧栏）让你用占位符描述页文件路径，而不必依赖固定的 <code>volume/language/chapter</code> 结构：</p><ul><li>占位符：<code>series</code>、<code>volume</code>、<code>chapter</code>、<code>language</code>、<code>page</code>。</li><li><code>*</code> 匹配任意一段；<code>**</code> 匹配一个可选段。</li><li>规则按顺序尝试，第一个命中生效。</li><li>对话框带实时预览：命中了多少文件和卷、哪些文件未识别、每一话包含哪些页。</li><li><strong>填入默认规则</strong> 恢复内置结构；<strong>恢复默认</strong> 放弃你的修改。</li><li><strong>保存规则</strong> 用新规则重新扫描图库。</li></ul><p>规则只影响识别，绝不会重命名或移动文件。</p><h2 id="导入、交换与恢复" tabindex="-1">导入、交换与恢复 <a class="header-anchor" href="#导入、交换与恢复" aria-label="Permalink to &quot;导入、交换与恢复&quot;">​</a></h2><p>侧栏里有四个不同的入口，各自负责不同的事：</p><table tabindex="0"><thead><tr><th>入口</th><th>用途</th></tr></thead><tbody><tr><td><strong>添加漫画</strong></td><td>把已有图片文件夹链接进图库。</td></tr><tr><td><strong>工程文件…</strong></td><td>导出或导入 <code>.mnproj</code> 包（图片 + 标注 + 模板 + 语言设置）。</td></tr><tr><td><strong>交换文件…</strong></td><td>传递 <code>.mntpl</code> 版式模板、<code>.mnexp</code> 导出模板，或单个 <code>.mnpage.json</code> 页面。</td></tr><tr><td><strong>备份 / 恢复</strong></td><td>把 <code>data/</code> 打包成 ZIP，或恢复之前的 ZIP。</td></tr></tbody></table><p>导入会先校验，原文件会备份到 <code>data/backups/</code>。文件内容和版本规则见<a href="/KomaYomi-docs/zh/guide/project-files">工程文件与格式</a>。</p><div class="tip custom-block"><p class="custom-block-title">导入顺序</p><p>想把标注恢复到同一台机器上，用<strong>备份</strong>恢复。换到另一台机器时导入<strong>工程</strong>。只想分享一个版式、一种导出样式或一页时，用<strong>交换文件</strong>。</p></div><h2 id="导航与性能" tabindex="-1">导航与性能 <a class="header-anchor" href="#导航与性能" aria-label="Permalink to &quot;导航与性能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>快捷键</th></tr></thead><tbody><tr><td>上一页 / 下一页</td><td><code>[</code> / <code>]</code></td></tr><tr><td>切格工作台</td><td><code>P</code></td></tr><tr><td>对照阅读</td><td><code>C</code></td></tr><tr><td>显示 / 隐藏侧栏</td><td><code>S</code></td></tr><tr><td>显示 / 隐藏笔记栏</td><td><code>N</code></td></tr><tr><td>打开导出对话框</td><td><code>E</code></td></tr><tr><td>帮助</td><td><code>?</code></td></tr></tbody></table><p>URL hash 可以深链接：<code>#/&lt;volume&gt;/&lt;chapter&gt;/&lt;page&gt;/&lt;panels|compare&gt;</code>。</p><p>缩略图按需生成，缓存在 <code>data/cache/thumbs/</code>。删除该目录是安全的，下次访问时会重新生成。图片格式从文件头判断，因此扩展名为 <code>.png</code> 但实际是 JPEG 的文件仍能正确显示。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>重命名文件会改变它的页位置。</strong> 配对按排序索引进行；在中间插入一页会把其后所有页后移。把新页加在末尾，或整话统一重命名。</li><li><strong>缺一种语言不是错误。</strong> 页面仍可打开，对照阅读会为缺失的语言显示占位。</li><li><strong>目录链接不是副本。</strong> 移动或删除原文件夹后，图库会失效。移动后请重新添加该文件夹。</li><li><strong>WebP 可以显示，但不会解码用于检测。</strong> 依赖自动切格时请使用 JPEG 或 PNG（见<a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a>）。</li><li><strong>以侧栏为准。</strong> 如果某一卷或某一话没有出现，先检查文件夹名大小写和语言别名。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a> —— 页面打开之后要做什么。</li><li><a href="/KomaYomi-docs/zh/guide/project-files">工程文件与格式</a> —— <code>.mnproj</code> 里有什么。</li><li><a href="/KomaYomi-docs/zh/guide/remote">远端存储与备份</a> —— 把图片放在 NAS 或 WebDAV 上。</li></ul>`,45)])])}const b=d(n,[["render",i]]);export{k as __pageData,b as default};
